package threads

import (
	"os"
	"strings"
	"testing"

	"github.com/Jlore-Studios/JackiOh/bot/go/internal/config"
	"github.com/Jlore-Studios/JackiOh/bot/go/internal/pyjson"
)

// The night bot's marker, as the Python reads `.harness/config.json`; config's stub holds none.
func TestMain(m *testing.M) {
	config.Marker = "<!-- jackioh-bot -->"
	os.Exit(m.Run())
}

// python.json is what bot/harness/threads.py answers for each input (generated by running it).
func expected(t *testing.T) *pyjson.Object {
	t.Helper()
	raw, err := os.ReadFile("testdata/python.json")
	if err != nil {
		t.Fatal(err)
	}
	data, err := pyjson.Loads(raw)
	if err != nil {
		t.Fatal(err)
	}
	return data.(*pyjson.Object)
}

func TestLinkedIssueMatchesPython(t *testing.T) {
	for _, pair := range expected(t).List("linked") {
		body := pair.([]any)[0]
		var got any
		if n := LinkedIssue(pyjson.New("body", body)); n != nil {
			got = *n
		}
		if want := pair.([]any)[1]; !pyjson.Equal(got, want) {
			t.Errorf("LinkedIssue(%q) = %v, want %v", body, got, want)
		}
	}
}

func TestIsBotMatchesPython(t *testing.T) {
	for _, pair := range expected(t).List("is_bot") {
		entry := pair.([]any)[0].(*pyjson.Object)
		if got, want := isBot(entry, "jgoetzmann-bot"), pair.([]any)[1].(bool); got != want {
			t.Errorf("isBot(%s) = %v, want %v", pyjson.Dumps(entry), got, want)
		}
	}
}

func TestClipCountsCodePoints(t *testing.T) {
	short := strings.Repeat("é", MaxChars)
	if clip(short) != short {
		t.Error("a text of MAX_CHARS code points was cut")
	}
	long := short + "é"
	if got := clip(long); got != short+"\n\n(cut here: too long)" {
		t.Errorf("clip cut to %d code points", len([]rune(got)))
	}
}
